PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','supervisor','student')), name TEXT NOT NULL, student_id INTEGER, supervisor_id INTEGER);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY, name TEXT NOT NULL, group_name TEXT NOT NULL, email TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bases(id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, contact TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS supervisors(id INTEGER PRIMARY KEY, name TEXT NOT NULL, position TEXT NOT NULL, email TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contracts(id INTEGER PRIMARY KEY, number TEXT UNIQUE NOT NULL, base_id INTEGER NOT NULL REFERENCES bases(id) ON DELETE RESTRICT, start_date TEXT NOT NULL, end_date TEXT NOT NULL, CHECK(start_date<=end_date));
CREATE TABLE IF NOT EXISTS placements(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT, base_id INTEGER NOT NULL REFERENCES bases(id) ON DELETE RESTRICT, supervisor_id INTEGER NOT NULL REFERENCES supervisors(id) ON DELETE RESTRICT, contract_id INTEGER NOT NULL REFERENCES contracts(id) ON DELETE RESTRICT, kind TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, CHECK(start_date<=end_date));
CREATE TABLE IF NOT EXISTS diaries(id INTEGER PRIMARY KEY, placement_id INTEGER NOT NULL REFERENCES placements(id) ON DELETE RESTRICT, date TEXT NOT NULL, content TEXT NOT NULL, hours INTEGER NOT NULL CHECK(hours BETWEEN 1 AND 12), status TEXT NOT NULL DEFAULT 'Ұсынылды' CHECK(status IN ('Ұсынылды','Қабылданды','Түзету қажет')), feedback TEXT NOT NULL DEFAULT '', UNIQUE(placement_id,date));
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY, placement_id INTEGER NOT NULL UNIQUE REFERENCES placements(id) ON DELETE RESTRICT, title TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Ұсынылды' CHECK(status IN ('Ұсынылды','Қабылданды','Түзету қажет')), feedback TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS grades(id INTEGER PRIMARY KEY, placement_id INTEGER NOT NULL UNIQUE REFERENCES placements(id) ON DELETE RESTRICT, discipline INTEGER NOT NULL CHECK(discipline BETWEEN 0 AND 100), diary INTEGER NOT NULL CHECK(diary BETWEEN 0 AND 100), report INTEGER NOT NULL CHECK(report BETWEEN 0 AND 100), defense INTEGER NOT NULL CHECK(defense BETWEEN 0 AND 100), comment TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, record_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY, placement_id INTEGER NOT NULL REFERENCES placements(id) ON DELETE RESTRICT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT, document_type TEXT NOT NULL CHECK(document_type IN ('diary','certificate','contract','report')), original_name TEXT NOT NULL, stored_name TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, file_size INTEGER NOT NULL CHECK(file_size BETWEEN 1 AND 10485760), status TEXT NOT NULL DEFAULT 'Ұсынылды', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_documents_placement ON documents(placement_id, created_at DESC);
